def min_operations(a, b):
    diff = abs(a - b)
    if diff == 0:
        return 0

    # Binary search to find the minimum k such that k * (k + 1) / 2 >= diff
    left, right = 0, int(diff**0.5) + 1
    while left < right:
        mid = (left + right) // 2
        if mid * (mid + 1) // 2 < diff:
            left = mid + 1
        else:
            right = mid

    # Check if we can achieve the exact match with the found k
    if left * (left + 1) // 2 >= diff:
        return left
    else:
        return left + 1

